import * as ui from "std/ui"

@jsonable
class AppState {
  bedtime: number;
  wakeBy: number;
  cycleLength: number;
  windowMinutes: number;
  settingsOpen: boolean;
}

function init(): AppState {
  return {bedtime: 1380, wakeBy: 420, cycleLength: 90, windowMinutes: 30, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_bedtime(state: AppState, value: number): AppState {
  return {bedtime: value, wakeBy: state.wakeBy, cycleLength: state.cycleLength, windowMinutes: state.windowMinutes, settingsOpen: state.settingsOpen};
}

function set_wakeBy(state: AppState, value: number): AppState {
  return {wakeBy: value, bedtime: state.bedtime, cycleLength: state.cycleLength, windowMinutes: state.windowMinutes, settingsOpen: state.settingsOpen};
}

function set_cycleLength(state: AppState, value: number): AppState {
  return {cycleLength: value, bedtime: state.bedtime, wakeBy: state.wakeBy, windowMinutes: state.windowMinutes, settingsOpen: state.settingsOpen};
}

function set_windowMinutes(state: AppState, value: number): AppState {
  return {windowMinutes: value, bedtime: state.bedtime, wakeBy: state.wakeBy, cycleLength: state.cycleLength, settingsOpen: state.settingsOpen};
}







function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, bedtime: state.bedtime, wakeBy: state.wakeBy, cycleLength: state.cycleLength, windowMinutes: state.windowMinutes};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
