      let sleepMinutes: number = (((wakeBy - bedtime) + minutesPerDay) % minutesPerDay);
      let fullCycles: number = math.floor(share(sleepMinutes, cycleLength));
      let cycleEnd: number = ((bedtime + (fullCycles * cycleLength)) % minutesPerDay);
    sections.push(ui.Section("content", "", "", [ui.TimeField("default", "Bedtime", state.bedtime, "set_bedtime")]));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "3 settings", settingsWord, "toggleSettings", 0, true, ""),
