  draft_contactName: string;
  draft_phoneNumber: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {contactName: "", phoneNumber: "", entries: emptyEntries, draft_contactName: "", draft_phoneNumber: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_contactName(state: AppState, value: string): AppState {
  return {contactName: value, phoneNumber: state.phoneNumber, entries: state.entries, draft_contactName: state.draft_contactName, draft_phoneNumber: state.draft_phoneNumber, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_phoneNumber(state: AppState, value: string): AppState {
  return {phoneNumber: value, contactName: state.contactName, entries: state.entries, draft_contactName: state.draft_contactName, draft_phoneNumber: state.draft_phoneNumber, removedEntries: state.removedEntries, removedAt: state.removedAt};
}



function set_draft_contactName(state: AppState, value: string): AppState {
  return {draft_contactName: value, contactName: state.contactName, phoneNumber: state.phoneNumber, entries: state.entries, draft_phoneNumber: state.draft_phoneNumber, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_phoneNumber(state: AppState, value: string): AppState {
  return {draft_phoneNumber: value, contactName: state.contactName, phoneNumber: state.phoneNumber, entries: state.entries, draft_contactName: state.draft_contactName, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_contactName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {contactName: strings.trim(state.draft_contactName), phoneNumber: strings.trim(state.draft_phoneNumber), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_contactName: "", draft_phoneNumber: "", contactName: state.contactName, phoneNumber: state.phoneNumber, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, contactName: state.contactName, phoneNumber: state.phoneNumber, draft_contactName: state.draft_contactName, draft_phoneNumber: state.draft_phoneNumber};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, contactName: state.contactName, phoneNumber: state.phoneNumber, draft_contactName: state.draft_contactName, draft_phoneNumber: state.draft_phoneNumber};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, contactName: state.contactName, phoneNumber: state.phoneNumber, entries: state.entries, draft_contactName: state.draft_contactName, draft_phoneNumber: state.draft_phoneNumber};
}





