import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  walkSpeedIndex: number;
  walkDistance: number;
  walkTime: number;
  settingsOpen: boolean;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, walkSpeedIndex: 1, walkDistance: 1.04, walkTime: 12.48, settingsOpen: false};
}

function countdownSeconds(state: AppState): number {
  let walkSpeedValues: number[] = [4, 5, 6];
  let walkSpeed: number = walkSpeedValues[state.walkSpeedIndex];
  let walkDistance: number = state.walkDistance;
  let walkTime: number = state.walkTime;
  let detourFactor: number = 1.3;
  return walkTime * 60;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, walkSpeedIndex: state.walkSpeedIndex, walkDistance: state.walkDistance, walkTime: state.walkTime, settingsOpen: state.settingsOpen}; }
  return {elapsedMs: total, running: false, finished: true, walkSpeedIndex: state.walkSpeedIndex, walkDistance: state.walkDistance, walkTime: state.walkTime, settingsOpen: state.settingsOpen};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, walkSpeedIndex: state.walkSpeedIndex, walkDistance: state.walkDistance, walkTime: state.walkTime, settingsOpen: state.settingsOpen};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, walkSpeedIndex: state.walkSpeedIndex, walkDistance: state.walkDistance, walkTime: state.walkTime, settingsOpen: state.settingsOpen};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, walkSpeedIndex: state.walkSpeedIndex, walkDistance: state.walkDistance, walkTime: state.walkTime, settingsOpen: state.settingsOpen};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_walkSpeed(state: AppState, value: number): AppState {
  return {walkSpeedIndex: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, walkDistance: state.walkDistance, walkTime: state.walkTime, settingsOpen: state.settingsOpen};
}

function set_walkDistance(state: AppState, value: number): AppState {
  return {walkDistance: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, walkSpeedIndex: state.walkSpeedIndex, walkTime: state.walkTime, settingsOpen: state.settingsOpen};
}

function set_walkTime(state: AppState, value: number): AppState {
  return {walkTime: value, elapsedMs: 0, running: false, finished: false, walkSpeedIndex: state.walkSpeedIndex, walkDistance: state.walkDistance, settingsOpen: state.settingsOpen};
}







function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, walkSpeedIndex: state.walkSpeedIndex, walkDistance: state.walkDistance, walkTime: state.walkTime};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Pharmacy Walk", "NEAREST PHARMACY · Nearest pharmacy to my location", "Find the closest pharmacy and time your walk there", "clock"));
  {
    sections.push(ui.Ticker("default", "clock", 200, state.running, "onTick"));
      let walkSpeedValues: number[] = [4, 5, 6];
      let walkSpeed: number = walkSpeedValues[state.walkSpeedIndex];
      let walkDistance: number = state.walkDistance;
      let walkTime: number = state.walkTime;
      let detourFactor: number = 1.3;
      let duration: number = countdownSeconds(state);
      let elapsed: number = math.min(state.elapsedMs / 1000, duration);
      let remaining: number = duration - elapsed;
    sections.push(ui.Section("hero", "", "", [ui.Hero("accent", "Walk to pharmacy", ui.durationToString(math.ceil(remaining)), "", [ui.ActionBar("spread", [ui.Button("primary", "Start", "onStart", 0, !state.running), ui.Button("secondary", "Stop", "onStop", 0, state.running), ui.Button("secondary", "Reset", "onReset", 0, true)])])]));
    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Walk distance", state.walkDistance, 0, 100, "set_walkDistance"), ui.NumberField("default", "Walk time (minutes)", state.walkTime, 1, 100, "set_walkTime")]));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "1 setting", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.Select("default", "Walking speed", ["Slow (4 km/h)", "Normal (5 km/h)", "Brisk (6 km/h)"], state.walkSpeedIndex, "set_walkSpeed")]))
    ]));
  }
  return ui.AppTheme("technical", "", sections);
}

