  stopName: string;
  stopAddress: string;
  entries: LogEntry[];
  draft_stopName: string;
  draft_stopAddress: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {stopName: "", stopAddress: "", entries: emptyEntries, draft_stopName: "", draft_stopAddress: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_stopName(state: AppState, value: string): AppState {
  return {stopName: value, stopAddress: state.stopAddress, entries: state.entries, draft_stopName: state.draft_stopName, draft_stopAddress: state.draft_stopAddress, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_stopAddress(state: AppState, value: string): AppState {
  return {stopAddress: value, stopName: state.stopName, entries: state.entries, draft_stopName: state.draft_stopName, draft_stopAddress: state.draft_stopAddress, removedEntries: state.removedEntries, removedAt: state.removedAt};
}



function set_draft_stopName(state: AppState, value: string): AppState {
  return {draft_stopName: value, stopName: state.stopName, stopAddress: state.stopAddress, entries: state.entries, draft_stopAddress: state.draft_stopAddress, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_stopAddress(state: AppState, value: string): AppState {
  return {draft_stopAddress: value, stopName: state.stopName, stopAddress: state.stopAddress, entries: state.entries, draft_stopName: state.draft_stopName, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_stopName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {stopName: strings.trim(state.draft_stopName), stopAddress: strings.trim(state.draft_stopAddress), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_stopName: "", draft_stopAddress: "", stopName: state.stopName, stopAddress: state.stopAddress, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, stopName: state.stopName, stopAddress: state.stopAddress, draft_stopName: state.draft_stopName, draft_stopAddress: state.draft_stopAddress};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, stopName: state.stopName, stopAddress: state.stopAddress, draft_stopName: state.draft_stopName, draft_stopAddress: state.draft_stopAddress};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, stopName: state.stopName, stopAddress: state.stopAddress, entries: state.entries, draft_stopName: state.draft_stopName, draft_stopAddress: state.draft_stopAddress};
}





