import * as ui from "std/ui"

@jsonable
class AppState {
  friendNumber: string;
  myScoreText: string;
}

function init(): AppState {
  return {friendNumber: "", myScoreText: "0"};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



