@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  sleepLengthIndex: number;
  volume: number;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, sleepLengthIndex: 2, volume: 60};
}

function countdownSeconds(state: AppState): number {
  let sleepLengthValues: number[] = [900, 1800, 2700, 3600, 5400];
  let sleepLength: number = sleepLengthValues[state.sleepLengthIndex];
  let volume: number = state.volume;
  let fadeOut: number = 60;
  return sleepLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, sleepLengthIndex: state.sleepLengthIndex, volume: state.volume}; }
  return {elapsedMs: total, running: false, finished: true, sleepLengthIndex: state.sleepLengthIndex, volume: state.volume};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, sleepLengthIndex: state.sleepLengthIndex, volume: state.volume};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, sleepLengthIndex: state.sleepLengthIndex, volume: state.volume};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, sleepLengthIndex: state.sleepLengthIndex, volume: state.volume};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_sleepLength(state: AppState, value: number): AppState {
  return {sleepLengthIndex: value, elapsedMs: 0, running: false, finished: false, volume: state.volume};
}

function set_volume(state: AppState, value: number): AppState {
  return {volume: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, sleepLengthIndex: state.sleepLengthIndex};
}







