import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  walkLengthIndex: number;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, walkLengthIndex: 2};
}

function countdownSeconds(state: AppState): number {
  let walkLengthValues: number[] = [900, 1800, 2700, 3600];
  let walkLength: number = walkLengthValues[state.walkLengthIndex];
  return walkLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, walkLengthIndex: state.walkLengthIndex}; }
  return {elapsedMs: total, running: false, finished: true, walkLengthIndex: state.walkLengthIndex};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, walkLengthIndex: state.walkLengthIndex};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, walkLengthIndex: state.walkLengthIndex};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, walkLengthIndex: state.walkLengthIndex};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_walkLength(state: AppState, value: number): AppState {
  return {walkLengthIndex: value, elapsedMs: 0, running: false, finished: false};
}







