      let walkLengthValues: number[] = [900, 1800, 2700, 3600];
      let walkLength: number = walkLengthValues[state.walkLengthIndex];
      let duration: number = countdownSeconds(state);
      let elapsed: number = math.min(state.elapsedMs / 1000, duration);
      let remaining: number = duration - elapsed;
    sections.push(ui.Section("hero", "", "", [ui.Hero("accent", "Torch on for", ui.durationToString(math.ceil(remaining)), "", [ui.ActionBar("spread", [ui.Button("primary", "Start", "onStart", 0, !state.running), ui.Button("secondary", "Stop", "onStop", 0, state.running), ui.Button("secondary", "Reset", "onReset", 0, true)])])]));
    sections.push(ui.Section("content", "", "", [ui.Select("default", "Walk length", ["15 minutes", "30 minutes", "45 minutes", "60 minutes"], state.walkLengthIndex, "set_walkLength")]));
